{
  "rules": [
    {
      "id": "recall_low_hp_enemy_present",
      "condition": "is this bot's hp below 50% of its max AND is an enemy minion, enemy tower, or enemy bearbot in sight?",
      "criteria": {
        "true": "hp < 50% and at least one enemy (minion/tower/bearbot) is visible",
        "false": "hp >= 50% OR no enemies are visible"
      },
      "action": {
        "kind": "move",
        "ability": null,
        "target_selector": "home"
      }
    },
    {
      "id": "recall_low_hp_no_enemy",
      "condition": "is this bot's hp below 50% of its max AND are no enemies in sight?",
      "criteria": {
        "true": "hp < 50% and no enemies are visible",
        "false": "hp >= 50% OR at least one enemy is visible"
      },
      "action": {
        "kind": "recall",
        "ability": null,
        "target_selector": "none"
      }
    },
    {
      "id": "recall_shop_afford_enemy_present",
      "condition": "can this bot afford the next item on its shopping list AND are no enemy bearbots in sight AND is an enemy minion or enemy tower in sight?",
      "criteria": {
        "true": "affords item, no enemy bearbot, but enemy minion/tower present",
        "false": "cannot afford item OR at least one enemy bearbot present OR no enemy minion/tower present"
      },
      "action": {
        "kind": "move",
        "ability": null,
        "target_selector": "home"
      }
    },
    {
      "id": "recall_shop_afford_no_enemy",
      "condition": "can this bot afford the next item on its shopping list AND are no enemies in sight?",
      "criteria": {
        "true": "affords item and no enemies visible",
        "false": "cannot afford item OR at least one enemy visible"
      },
      "action": {
        "kind": "recall",
        "ability": null,
        "target_selector": "none"
      }
    },
    {
      "id": "retreat_wealthy_weak_fight",
      "condition": "does this bot carry at least 300 gold AND is its side weaker in the fight near it?",
      "criteria": {
        "true": "gold >= 300 and side is weaker in nearby fight",
        "false": "gold < 300 OR side is not weaker (even or stronger) in nearby fight"
      },
      "action": {
        "kind": "move",
        "ability": null,
        "target_selector": "home"
      }
    },
    {
      "id": "punish_tower_diver",
      "condition": "is an enemy bearbot under this bot's own tower?",
      "criteria": {
        "true": "enemy bearbot is inside range of own tower (tower diver)",
        "false": "no enemy bearbot inside range of own tower"
      },
      "action": {
        "kind": "attack",
        "ability": null,
        "target_selector": "tower_diver"
      }
    },
    {
      "id": "siege_tower_wave_present",
      "condition": "is this bot inside an enemy tower's range AND does that tower have this bot's own minions in its range?",
      "criteria": {
        "true": "inside enemy tower range and own minions are also in that range (tower shoots minions first)",
        "false": "not inside enemy tower range OR no own minions in that enemy tower's range"
      },
      "action": {
        "kind": "attack",
        "ability": null,
        "target_selector": "nearest_enemy_tower"
      }
    },
    {
      "id": "retreat_weak_fight_own_tower",
      "condition": "is this bot's side weaker in the fight near it?",
      "criteria": {
        "true": "side is weaker in nearby fight",
        "false": "side is even or stronger in nearby fight"
      },
      "action": {
        "kind": "move",
        "ability": null,
        "target_selector": "own_tower"
      }
    },
    {
      "id": "hunt_highest_bounty",
      "condition": "is an enemy bearbot in sight?",
      "criteria": {
        "true": "at least one enemy bearbot is visible",
        "false": "no enemy bearbots are visible"
      },
      "action": {
        "kind": "attack",
        "ability": null,
        "target_selector": "highest_bounty_enemy"
      }
    },
    {
      "id": "attack_lowest_hp_minion_present",
      "condition": "is an enemy minion in sight?",
      "criteria": {
        "true": "at least one enemy minion is visible",
        "false": "no enemy minions are visible"
      },
      "action": {
        "kind": "attack",
        "ability": null,
        "target_selector": "nearest_enemy_minion"
      }
    },
    {
      "id": "move_to_nearest_ally",
      "condition": "is an allied minion near this bot?",
      "criteria": {
        "true": "at least one allied minion is nearby",
        "false": "no allied minions are nearby"
      },
      "action": {
        "kind": "move",
        "ability": null,
        "target_selector": "nearby_minion"
      }
    },
    {
      "id": "bandstand_open_no_enemy_hp_ok",
      "condition": "is the Bandstand open AND are no enemy bearbots in sight AND is this bot's hp above 50% of its max?",
      "criteria": {
        "true": "Bandstand open, no enemy bearbot, hp > 50%",
        "false": "Bandstand not open OR enemy bearbot present OR hp <= 50%"
      },
      "action": {
        "kind": "move",
        "ability": null,
        "target_selector": "bandstand"
      }
    },
    {
      "id": "bandstand_contested_hp_ok",
      "condition": "is the Bandstand open AND is it contested or making progress by enemy team AND is this bot's hp above 40% of its max?",
      "criteria": {
        "true": "Bandstand open, contested/progressing, hp > 40%",
        "false": "Bandstand not open OR not contested/progressing OR hp <= 40%"
      },
      "action": {
        "kind": "move",
        "ability": null,
        "target_selector": "bandstand"
      }
    },
    {
      "id": "bandstand_upcoming_close",
      "condition": "will the Bandstand open within 10 seconds AND is it less than 400 units from this bot?",
      "criteria": {
        "true": "Bandstand opens <= 10s and distance < 400",
        "false": "Bandstand opens > 10s OR distance >= 400"
      },
      "action": {
        "kind": "move",
        "ability": null,
        "target_selector": "bandstand"
      }
    },
    {
      "id": "finish_kill_ability_ready_low_hp",
      "condition": "is this bot's primary ability ready AND is an enemy bearbot in sight with less than 100 hp?",
      "criteria": {
        "true": "ability ready and enemy bearbot < 100hp visible",
        "false": "ability not ready OR no enemy bearbot < 100hp visible"
      },
      "action": {
        "kind": "ability",
        "ability": "chord",
        "target_selector": "lowest_hp_enemy"
      }
    },
    {
      "id": "attack_lowest_hp_no_ability",
      "condition": "is an enemy bearbot in sight with less than 100 hp?",
      "criteria": {
        "true": "enemy bearbot < 100hp visible",
        "false": "no enemy bearbot < 100hp visible"
      },
      "action": {
        "kind": "attack",
        "ability": null,
        "target_selector": "lowest_hp_enemy"
      }
    },
    {
      "id": "fall_back_tower_shoots",
      "condition": "will an enemy tower shoot this bot?",
      "criteria": {
        "true": "enemy tower will shoot this bot (no minions in range to block)",
        "false": "enemy tower will not shoot this bot"
      },
      "action": {
        "kind": "move",
        "ability": null,
        "target_selector": "own_tower"
      }
    },
    {
      "id": "close_match_attack_tower",
      "condition": "is it more than 480 seconds into the match AND can this bot see an enemy tower?",
      "criteria": {
        "true": "time > 480s and enemy tower visible",
        "false": "time <= 480s OR no enemy tower visible"
      },
      "action": {
        "kind": "attack",
        "ability": null,
        "target_selector": "nearest_enemy_tower"
      }
    },
    {
      "id": "default_push_lane",
      "condition": "is there no other rule matching?",
      "criteria": {
        "true": "no other conditions matched",
        "false": "some other condition matched"
      },
      "action": {
        "kind": "move",
        "ability": null,
        "target_selector": "push_lane"
      }
    }
  ],
  "default_action": {
    "kind": "move",
    "ability": null,
    "target_selector": "push_lane"
  },
  "build": [
    "metronome",
    "amp",
    "road-case",
    "click-track",
    "bass-strings",
    "arpeggiator",
    "backline",
    "wall-of-sound"
  ]
}

