    {
      "id": "recall_low_hp_enemy_present",
      "condition": "is this bearbot's hp below 50% of its max AND is an enemy minion, enemy tower, or enemy bearbot in sight?",
      "criteria": {
        "true": "hp < 50% and at least one enemy unit (minion/tower/bearbot) is visible",
        "false": "hp >= 50% OR no enemy units are visible"
      },
      "action": {
        "kind": "move",
        "ability": null,
        "target_selector": "home"
      }
    },
    {
      "id": "recall_low_hp_no_enemy",
      "condition": "is this bearbot's hp below 50% of its max AND are no enemies in sight?",
      "criteria": {
        "true": "hp < 50% and no enemy units are visible",
        "false": "hp >= 50% OR at least one enemy unit is visible"
      },
      "action": {
        "kind": "recall",
        "ability": null,
        "target_selector": "none"
      }
    },
    {
      "id": "shop_afford_no_enemy_minion_tower",
      "condition": "can this bearbot afford the next item on its shopping list AND are no enemy bearbots in sight AND is an enemy minion or enemy tower in sight?",
      "criteria": {
        "true": "affords next item, no enemy bearbots visible, at least one enemy minion/tower visible",
        "false": "cannot afford OR enemy bearbot visible OR no enemy minion/tower visible"
      },
      "action": {
        "kind": "move",
        "ability": null,
        "target_selector": "home"
      }
    },
    {
      "id": "shop_afford_no_enemy_any",
      "condition": "can this bearbot afford the next item on its shopping list AND are no enemies in sight?",
      "criteria": {
        "true": "affords next item and no enemy units visible",
        "false": "cannot afford OR at least one enemy unit visible"
      },
      "action": {
        "kind": "recall",
        "ability": null,
        "target_selector": "none"
      }
    },
    {
      "id": "spend_gold_weak_fight",
      "condition": "does this bearbot carry at least 300 gold AND is its side weaker in the fight near it?",
      "criteria": {
        "true": "gold >= 300 and fight verdict is 'weaker'",
        "false": "gold < 300 OR fight verdict is not 'weaker'"
      },
      "action": {
        "kind": "move",
        "ability": null,
        "target_selector": "home"
      }
    },
    {
      "id": "punish_tower_diver",
      "condition": "is an enemy bearbot under this bearbot's own tower?",
      "criteria": {
        "true": "an enemy bearbot is inside the range of this bearbot's own tower",
        "false": "no enemy bearbot is inside the range of this bearbot's own tower"
      },
      "action": {
        "kind": "attack",
        "ability": null,
        "target_selector": "tower_diver"
      }
    },
    {
      "id": "siege_tower_minions_present",
      "condition": "is this bearbot inside an enemy tower's range AND does that tower have this bearbot's own minions in its range?",
      "criteria": {
        "true": "inside enemy tower range and enemy tower has friendly minions in range",
        "false": "not inside enemy tower range OR enemy tower has no friendly minions in range"
      },
      "action": {
        "kind": "attack",
        "ability": null,
        "target_selector": "nearest_enemy_tower"
      }
    },
    {
      "id": "fall_back_weak_fight",
      "condition": "is this bearbot's side weaker in the fight near it?",
      "criteria": {
        "true": "fight verdict is 'weaker'",
        "false": "fight verdict is not 'weaker'"
      },
      "action": {
        "kind": "move",
        "ability": null,
        "target_selector": "own_tower"
      }
    },
    {
      "id": "hunt_carrier",
      "condition": "is an enemy bearbot in sight?",
      "criteria": {
        "true": "at least one enemy bearbot is visible",
        "false": "no enemy bearbots are visible"
      },
      "action": {
        "kind": "attack",
        "ability": null,
        "target_selector": "highest_bounty_enemy"
      }
    },
    {
      "id": "attack_lowest_hp_enemy",
      "condition": "is an enemy bearbot in sight AND does it have less than 100 hp?",
      "criteria": {
        "true": "enemy bearbot visible and its hp < 100",
        "false": "no enemy bearbot visible OR enemy bearbot hp >= 100"
      },
      "action": {
        "kind": "attack",
        "ability": null,
        "target_selector": "lowest_hp_enemy"
      }
    },
    {
      "id": "attack_nearest_enemy_minion",
      "condition": "is an enemy minion in sight?",
      "criteria": {
        "true": "at least one enemy minion is visible",
        "false": "no enemy minions are visible"
      },
      "action": {
        "kind": "attack",
        "ability": null,
        "target_selector": "nearest_enemy_minion"
      }
    },
    {
      "id": "move_to_nearest_ally_minion",
      "condition": "is an allied minion near this bearbot?",
      "criteria": {
        "true": "at least one allied minion is within 260 units",
        "false": "no allied minions are within 260 units"
      },
      "action": {
        "kind": "move",
        "ability": null,
        "target_selector": "nearby_minion"
      }
    },
    {
      "id": "bandstand_open_no_enemy_hp_above_half",
      "condition": "is the Bandstand open AND are no enemy bearbots in sight AND is this bearbot's hp above 50% of its max?",
      "criteria": {
        "true": "Bandstand open, no enemy bearbots visible, hp > 50%",
        "false": "Bandstand not open OR enemy bearbot visible OR hp <= 50%"
      },
      "action": {
        "kind": "move",
        "ability": null,
        "target_selector": "bandstand"
      }
    },
    {
      "id": "bandstand_contested_hp_above_40",
      "condition": "is the Bandstand open AND is it contested OR is the enemy team making progress on it AND is this bearbot's hp above 40% of its max?",
      "criteria": {
        "true": "Bandstand open and (contested or enemy progressing) and hp > 40%",
        "false": "Bandstand not open OR (not contested and no enemy progress) OR hp <= 40%"
      },
      "action": {
        "kind": "move",
        "ability": null,
        "target_selector": "bandstand"
      }
    },
    {
      "id": "bandstand_upcoming_near",
      "condition": "will the Bandstand open within 10 seconds AND is it less than 400 units from this bearbot?",
      "criteria": {
        "true": "Bandstand opens <= 10s and distance < 400",
        "false": "Bandstand opens > 10s OR distance >= 400"
      },
      "action": {
        "kind": "move",
        "ability": null,
        "target_selector": "bandstand"
      }
    },
    {
      "id": "fall_back_enemy_tower_shoots",
      "condition": "will an enemy tower shoot this bearbot?",
      "criteria": {
        "true": "enemy tower is in range and will target this bearbot (no friendly minions shielding)",
        "false": "enemy tower not in range OR shielded by friendly minions"
      },
      "action": {
        "kind": "move",
        "ability": null,
        "target_selector": "own_tower"
      }
    },
    {
      "id": "finish_kill_ability_ready_lowest_hp",
      "condition": "is this bearbot's primary ability ready AND is an enemy bearbot in sight with less than 100 hp?",
      "criteria": {
        "true": "ability cooldown <= 0 and enemy bearbot visible with hp < 100",
        "false": "ability not ready OR no enemy bearbot visible OR enemy bearbot hp >= 100"
      },
      "action": {
        "kind": "ability",
        "ability": "chord",
        "target_selector": "lowest_hp_enemy"
      }
    },
    {
      "id": "attack_nearest_enemy_tower_late_game",
      "condition": "is it more than 480 seconds into the match AND can this bearbot see an enemy tower?",
      "criteria": {
        "true": "time > 480s and at least one enemy tower is visible",
        "false": "time <= 480s OR no enemy towers visible"
      },
      "action": {
        "kind": "attack",
        "ability": null,
        "target_selector": "nearest_enemy_tower"
      }
    }
  ],
  "default_action": {
    "kind": "move",
    "ability": null,
    "target_selector": "push_lane"
  },
  "build": [
    "metronome",
    "amp",
    "road-case",
    "click-track",
    "bass-strings",
    "arpeggiator",
    "backline",
    "wall-of-sound"
  ]
}

